function svg(name, cls) {
  const a = ART[name];
  if (!a) return '';
  return `<div class="${cls}"><svg viewBox="${a.viewBox}" role="img"
    aria-label="Illustration of this concept">${a.inner}</svg></div>`;
}

/** Hero illustration for a lesson's lead card, or '' when it has none. */
export function lessonArt(lessonId) {
  return svg(LESSON_ART[lessonId], 'ba-art hero');
}

/** Illustration for one teaching section, or '' when it has none. */
export function sectionArt(lessonId, index) {
  return svg(SECTION_ART[lessonId + '#' + index], 'ba-art');
}
